def build_constraint_1(qc, problem_qubits, flag, scratch):
    # (x0 OR NOT x1 OR x2)  → false when x0=0, x1=1, x2=0
    # conds: NOT x0, x1, NOT x2
    conds = [(0, True), (1, False), (2, True)]
    # Compute cond1 AND cond2 into scratch[0]
    if conds[0][1]:
