import qiskit

def _ccccx(qc, controls, target, ancilla):
    """
    Implements a 4-controlled X gate (C^4X) using two ancilla qubits.
    The ancillas are returned to |0>.
    """
    a0, a1 = ancilla
    # Compute a0 = controls[0] & controls[1]
    qc.ccx(controls[0], controls[1], a0)
    # Compute a1 = controls[2] & controls[3]
    qc.ccx(controls[2], controls[3], a1)
    # Flip target if a0 & a1
    qc.ccx(a0, a1, target)
    # Uncompute a1
    qc.ccx(controls[2], controls[3], a1)
    # Uncompute a0
    qc.ccx(controls[0], controls[1], a0)

# Patterns where the two vertices decode to the same color
EQUAL_PATTERNS = [
    (0,0,0,0),  # both color 0: 00 & 00
    (0,0,1,1),  # both color 0: 00 & 11
    (1,1,0,0),  # both color 0: 11 & 00
    (1,1,1,1),  # both color 0: 11 & 11
    (0,1,0,1),  # both color 1
    (1,0,1,0),  # both color 2
]

